use super::prelude::*;

/// Charge — transform 2 draw-pile cards into MinionDiveBomb.
///
/// C# `Charge.OnPlay` (v0.107.1 Charge.cs): `CardSelectCmd.FromCombatPile(ctx,
/// PileType.Draw.GetPile(Owner), Owner, prefs(prompt, CardsVar=2))` → for each
/// selected card `CardCmd.TransformTo<MinionDiveBomb>(item)` (and `Upgrade` it
/// iff Charge is upgraded). The single-arg `CardSelectorPrefs(prompt, 2)` ctor
/// sets `MinSelect == MaxSelect == 2`, so `RequireManualConfirmation` is FALSE;
/// per the select-cmd the auto-apply fast path `if (!RequireManualConfirmation
/// && cards.Count <= MinSelect)` fires ONLY when the draw pile has ≤2 cards.
/// With 3+ draw cards it SURFACES a forced two-pick (`min=max=2`) `card_select`.
///
/// v0.107.1 bead 1a.12: `FromSimpleGrid(orderby c.Rarity, c.Id …)` →
/// `FromCombatPile(PileType.Draw.GetPile(Owner) …)`. The `(rarity, id)` sort is
/// NOT gone: `CardSelectCmd.FromCombatPile` (`CardSelectCmd.cs`) re-applies
/// `orderby c.Rarity, c.Id` for any `PileType.Draw` pile, but ONLY in its
/// interactive (`Selector`) branch. Its auto-resolve fast path
/// (`!RequireManualConfirmation && count <= MinSelect`) returns the pile in RAW
/// order. So: the ≤2-draw auto-take keeps raw pile order; the 3+-draw surfaced
/// screen is sorted `(Rarity, then Id == card Entry name)`, exactly like the
/// Stratagem (`hooks::after_shuffle_stratagem`) and ForegoneConclusion
/// draw-select screens.
///
/// The select surfaces as a
/// [`sts2_core::ChoiceKind::TransformDrawCardsToMinionDiveBomb`] two-pick choice
/// over the `(Rarity, Id)`-sorted draw pile; the resolver mints each
/// `MinionDiveBomb` (upgraded iff CHARGE is upgraded, re-derived from the
/// Play-pile tail) and transforms the chosen cards. The ≤2-draw path stays
/// inline as a faithful auto-apply (`count = min(2, len)`, mirroring the C#
/// `cards.Count <= MinSelect` fast path, raw order). Same draw-pile transform
/// family as Seance (TransformDrawCardToSoul, count 1).
// C# source: ../sts2-wiki/decompiled/v0.107.1/MegaCrit.Sts2.Core.Models.Cards/Charge.cs
pub(crate) fn play_charge(state: &mut CombatState, _t: Option<CreatureUid>) -> EffectResult {
    let upgraded = current_card_upgraded(state);
    // Raw draw-pile order for the ≤2 auto-take fast path; the 3+ interactive
    // branch below re-sorts by (Rarity, Id) per C# FromCombatPile.
    let ordered: Vec<sts2_core::CardUid> = state.player.draw.iter().copied().collect();
    if ordered.len() <= 2 {
        // C# fast path: cards.Count <= MinSelect(2) → auto-apply with no
        // prompt. count = min(2, len) covers the 0/1/2-draw edges.
        transform_first_n_to(
            state,
            &ordered,
            ordered.len().min(2),
            CardId::MinionDiveBomb,
            upgraded,
        );
        return EffectResult::Resolved;
    }
    // 3+ draw cards: open a forced two-pick choice. C# `Charge.OnPlay` uses
    // `CardSelectCmd.FromCombatPile(PileType.Draw.GetPile(Owner), prefs(2))`.
    // The auto-resolve fast path (`count <= MinSelect`, i.e. the ≤2 branch
    // above) returns the pile in RAW order, but the INTERACTIVE (`Selector`)
    // branch — taken here with 3+ cards — re-applies `orderby c.Rarity, c.Id`
    // for any `PileType.Draw` pile (`CardSelectCmd.cs` FromCombatPile). So the
    // surfaced screen is sorted by `(Rarity, Id)`, exactly like the Stratagem /
    // ForegoneConclusion draw-select screens. A prior port read bead 1a.12's
    // `FromSimpleGrid → FromCombatPile` swap as dropping the sort for BOTH
    // paths, so an index-replay harness picked the wrong draw slots off the
    // screen (Regent sweep DRAW_ORDER|CHARGE: Charge transformed the raw-order
    // slots {0,1} where C# transformed the (rarity, id)-sorted slots). The
    // resolver mints each MinionDiveBomb (upgraded iff CHARGE is upgraded,
    // re-derived from the Play-pile tail) and transforms the chosen cards.
    let mut keyed: Vec<(u8, &'static str, sts2_core::CardUid)> = ordered
        .iter()
        .filter_map(|&uid| {
            let card = state.cards.get(uid.0.get() as usize - 1)?;
            Some((
                crate::cards::spec_index::card_rarity_rank_csharp_in(
                    card.card_id,
                    state.game_version,
                ),
                sts2_core::cards::card_model_entry(card.card_id),
                uid,
            ))
        })
        .collect();
    keyed.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(b.1)));
    let options: Vec<sts2_core::ChoiceOption> = keyed
        .iter()
        .filter_map(|&(_, _, uid)| {
            let card = state.cards.get(uid.0.get() as usize - 1)?;
            Some(sts2_core::ChoiceOption {
                card_id: card.card_id,
                upgraded: card.upgraded,
                card_uid: Some(uid),
                source_pile: Some(sts2_core::cards::PileKind::Draw),
            })
        })
        .collect();
    state.request_card_choice(
        sts2_core::ChoiceKind::TransformDrawCardsToMinionDiveBomb,
        options,
        2,
        2,
        false,
    );
    EffectResult::Resolved
}

