#[cfg(test)]
mod tests {
    use super::*;
    use smallvec::SmallVec;

    fn mint(state: &mut CombatState, id: CardId, upgraded: bool) -> sts2_core::CardUid {
        let mut card =
            crate::cards::spec_index::card_pod_from_id(id, upgraded).expect("spec exists");
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = sts2_core::CardUid::new(raw).expect("nz");
        card.uid = uid;
        state.cards.push(card);
        uid
    }

    /// 3+ draw-pile cards: v0.107.1 `Charge.OnPlay` uses
    /// `CardSelectCmd.FromCombatPile(PileType.Draw.GetPile(Owner) …)` —
    /// `prefs(prompt, 2)` surfaces a forced two-pick `card_select`
    /// (count > MinSelect == 2). The interactive `Selector` branch of
    /// `FromCombatPile` re-applies `orderby c.Rarity, c.Id` for `PileType.Draw`,
    /// so the options are **(Rarity, Id)-sorted**, NOT raw pile order.
    /// Resolving a 2-index selection transforms exactly those two draw slots
    /// into MinionDiveBomb.
    #[test]
    fn charge_three_draw_cards_opens_transform_choice_and_transforms_chosen() {
        crate::cards::dispatch::install_default_registry();
        sts2_core::register_card_factory(crate::cards::spec_index::card_pod_from_id);
        let mut state = CombatState::default();
        // Alive player -- dead trips the request_card_choice ending guard.
        state.player.current_hp = 80;
        // Three observable draw-pile cards. The raw pile order [Strike, Defend,
        // Defend] DIFFERS from the (rarity, id) sort the interactive screen
        // applies: both are Basic rarity so the sort keys on the entry-id string
        // ("DEFEND_NECROBINDER" < "STRIKE_NECROBINDER"), reordering the SCREEN to
        // [Defend, Defend, Strike] — so option[0] must be a Defend, proving the
        // sort is applied.
        let s1 = mint(&mut state, CardId::StrikeNecrobinder, false);
        let d1 = mint(&mut state, CardId::DefendNecrobinder, false);
        let d2 = mint(&mut state, CardId::DefendNecrobinder, false);
        state.player.draw.extend([s1, d1, d2]);
        // The resolving (un-upgraded) CHARGE sits on top of the Play pile.
        let charge = mint(&mut state, CardId::Charge, false);
        state.player.play.push(charge);

        let r = play_charge(&mut state, None);
        assert_eq!(r, EffectResult::Resolved);
        let pc = state
            .pending_choice
            .as_ref()
            .expect("Charge opens a choice with 3+ draw cards");
        assert_eq!(
            pc.kind,
            sts2_core::ChoiceKind::TransformDrawCardsToMinionDiveBomb
        );
        assert_eq!(pc.min_select, 2);
        assert_eq!(pc.max_select, 2);
        assert_eq!(pc.options.len(), 3, "all three draw cards are options");
        // Options follow the (Rarity, Id) sort the interactive FromCombatPile
        // Selector branch applies to Draw piles: both Defends (id
        // "DEFEND_NECROBINDER") sort before the Strike (id "STRIKE_NECROBINDER");
        // the two Defends tie so the stable sort keeps their pile order [d1, d2].
        let option_uids: Vec<_> = pc.options.iter().map(|o| o.card_uid).collect();
        assert_eq!(
            option_uids,
            vec![Some(d1), Some(d2), Some(s1)],
            "options in (rarity, id) order [Defend, Defend, Strike], NOT raw pile order"
        );
        assert_eq!(
            pc.options[0].card_id,
            CardId::DefendNecrobinder,
            "option[0] is a (rarity, id)-sorted Defend; raw pile order would have put the Strike first"
        );
        for o in &pc.options {
            assert_eq!(o.source_pile, Some(sts2_core::cards::PileKind::Draw));
        }

        // Pick options 0 and 2 — those two draw slots must become MinionDiveBomb.
        // `transform_card` rebinds each chosen slot to a FRESH uid (the old
        // uids leave the draw pile), so we assert on the resulting draw pile.
        let pick0 = pc.options[0].card_uid.expect("uid");
        let pick2 = pc.options[2].card_uid.expect("uid");
        let unpicked = pc.options[1].card_uid.expect("uid");
        let selection: SmallVec<[u8; 4]> = [0u8, 2u8].into_iter().collect();
        let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
        assert_eq!(res, sts2_core::StepResult::Advanced);
        assert!(state.pending_choice.is_none());

        // The two chosen draw slots are rebound to fresh MinionDiveBomb cards;
        // the unpicked card keeps its uid and is untouched.
        assert!(
            !state.player.draw.contains(&pick0),
            "first picked draw slot rebound to a new card"
        );
        assert!(
            !state.player.draw.contains(&pick2),
            "second picked draw slot rebound to a new card"
        );
        assert!(
            state.player.draw.contains(&unpicked),
            "unpicked draw card untouched"
        );
        assert_ne!(
            state.cards[unpicked.0.get() as usize - 1].card_id,
            CardId::MinionDiveBomb,
            "unpicked draw card not transformed"
        );
        // Exactly two draw cards are now MinionDiveBomb, both un-upgraded.
        let bombs: Vec<&_> = state
            .player
            .draw
            .iter()
            .map(|&u| &state.cards[u.0.get() as usize - 1])
            .filter(|c| c.card_id == CardId::MinionDiveBomb)
            .collect();
        assert_eq!(
            bombs.len(),
            2,
            "exactly two draw cards became MinionDiveBomb"
        );
        assert!(
            bombs.iter().all(|c| !c.upgraded),
            "un-upgraded CHARGE mints un-upgraded MinionDiveBomb"
        );
    }

    /// Upgraded CHARGE: the minted MinionDiveBomb tokens must be upgraded
    /// (C# `if (IsUpgraded) Upgrade(added)`). The upgrade flag is re-derived
    /// from the Play-pile-tail CHARGE at resolution time.
    #[test]
    fn charge_upgraded_mints_upgraded_minions() {
        crate::cards::dispatch::install_default_registry();
        sts2_core::register_card_factory(crate::cards::spec_index::card_pod_from_id);
        let mut state = CombatState::default();
        // Alive player -- dead trips the request_card_choice ending guard.
        state.player.current_hp = 80;
        let a = mint(&mut state, CardId::StrikeNecrobinder, false);
        let b = mint(&mut state, CardId::DefendNecrobinder, false);
        let c = mint(&mut state, CardId::DefendNecrobinder, false);
        state.player.draw.extend([a, b, c]);
        // Upgraded CHARGE on the Play-pile tail.
        let charge = mint(&mut state, CardId::Charge, true);
        state.player.play.push(charge);

        let r = play_charge(&mut state, None);
        assert_eq!(r, EffectResult::Resolved);
        assert!(
            state.pending_choice.is_some(),
            "choice opens with 3 draw cards"
        );
        let selection: SmallVec<[u8; 4]> = [0u8, 1u8].into_iter().collect();
        let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
        assert_eq!(res, sts2_core::StepResult::Advanced);
        // The two minted MinionDiveBomb cards (rebound draw slots) are upgraded.
        let bombs: Vec<&_> = state
            .player
            .draw
            .iter()
            .map(|&u| &state.cards[u.0.get() as usize - 1])
            .filter(|c| c.card_id == CardId::MinionDiveBomb)
            .collect();
        assert_eq!(bombs.len(), 2, "two draw cards became MinionDiveBomb");
        assert!(
            bombs.iter().all(|c| c.upgraded),
            "upgraded CHARGE mints upgraded MinionDiveBomb"
        );
    }

    /// Exactly two draw cards: C# `FromSimpleGrid` auto-applies (cards.Count
    /// <= MinSelect == 2) with NO prompt; Rust transforms both draw cards into
    /// MinionDiveBomb inline.
    #[test]
    fn charge_two_draw_cards_auto_applies_no_choice() {
        crate::cards::dispatch::install_default_registry();
        let mut state = CombatState::default();
        // A live player: a transform is refused once the combat is ending.
        state.player.current_hp = 1;
        let a = mint(&mut state, CardId::StrikeNecrobinder, false);
        let b = mint(&mut state, CardId::DefendNecrobinder, false);
        state.player.draw.extend([a, b]);
        let charge = mint(&mut state, CardId::Charge, false);
        state.player.play.push(charge);

        let r = play_charge(&mut state, None);
        assert_eq!(r, EffectResult::Resolved);
        assert!(
            state.pending_choice.is_none(),
            "no choice surfaced for ≤2 draw cards (cards.Count <= MinSelect)"
        );
        // `transform_card_in_place` rebinds both draw slots to fresh
        // MinionDiveBomb cards (the old uids leave the draw pile).
        assert!(!state.player.draw.contains(&a), "first draw slot rebound");
        assert!(!state.player.draw.contains(&b), "second draw slot rebound");
        assert_eq!(state.player.draw.len(), 2, "still two draw cards");
        assert!(
            state
                .player
                .draw
                .iter()
                .all(|&u| state.cards[u.0.get() as usize - 1].card_id == CardId::MinionDiveBomb),
            "both draw cards transformed into MinionDiveBomb inline"
        );
    }
}
